# -*- coding: utf-8 -*-
# Catechism bank — the Iẓhār Q&A, bāb 1 (the governor), items 49–71.
ITEMS = [
 {"n": 49, "q": {"tr": "Ef'âl-i kulûba mülhak olan fiiller nerelerde ef'âl-i kulûba mülhaktır?", "en": "In what respects are the verbs attached to the verbs of the heart attached to them?"},
  "a": {"tr": "Yalnız mübtedâ ve haber üzerine girmekte, karinesiz mef'ûllerinin ikisini birlikte veya birini hazfetmenin câiz olmamasında ve karine ile ikisinden birinin hazfinin az olmasında mülhaktırlar.", "en": "Only in entering upon a mubtadaʾ and khabar, in not allowing both objects or one to be dropped without a clue, and in the rarity of dropping one with a clue."},
  "ar": ["الْمُلْحَقُ بِأَفْعَالِ الْقُلُوبِ"], "notes": ["al-mutaaddi-wa-afal-al-qulub", "zanna-wa-akhawatuha"]},
 {"n": 50, "q": {"tr": "Ef'âl-i kulûbun tarifi nedir? Hangileridir?", "en": "How are the verbs of the heart defined, and which are they?"},
  "a": {"tr": "Kalbî bir fiile delâlet edip mübtedâ ve haber üzerine giren ve ikisini mef'ûliyyet üzere nasb eden fiillerdir: عَلِمْتُ، رَأَيْتُ، وَجَدْتُ، زَعَمْتُ، ظَنَنْتُ، خِلْتُ، حَسِبْتُ، هَبْ.", "en": "Verbs indicating an act of the heart, entering upon a mubtadaʾ and khabar and putting both in naṣb as objects: عَلِمْتُ، رَأَيْتُ، وَجَدْتُ، زَعَمْتُ، ظَنَنْتُ، خِلْتُ، حَسِبْتُ، هَبْ."},
  "ar": ["أَفْعَالٌ دَالَّةٌ عَلَى فِعْلٍ قَلْبِيٍّ دَاخِلَةٌ عَلَى الْمُبْتَدَإِ وَالْخَبَرِ نَاصِبَةٌ إِيَّاهُمَا عَلَى الْمَفْعُولِيَّةِ"], "notes": ["zanna-wa-akhawatuha", "al-mutaaddi-wa-afal-al-qulub"]},
 {"n": 51, "q": {"tr": "Ef'âl-i kulûbun hâssaları nelerdir?", "en": "What are the special properties of the verbs of the heart?"},
  "a": {"tr": "Ma'mûlleri arasında veya ma'mûllerinden sonra geldiğinde amel ettirmenin ve ettirmemenin câiz olması (زَيْدًا عَلِمْتُ مُنْطَلِقًا / زَيْدٌ عَلِمْتُ مُنْطَلِقٌ؛ زَيْدًا مُنْطَلِقًا عَلِمْتُ / زَيْدٌ مُنْطَلِقٌ عَلِمْتُ); fâil ve mef'ûlünün aynı mânâya iki muttasıl zamir olabilmesi (عَلِمْتُنِي قَائِمًا، عَلِمْتَكَ قَائِمًا); mef'ûlleri üzerine أَنَّ'nin girebilmesi (عَلِمْتُ أَنَّ زَيْدًا قَائِمٌ).", "en": "Standing between or after their governed words they may govern or be suspended (زَيْدًا عَلِمْتُ مُنْطَلِقًا / زَيْدٌ عَلِمْتُ مُنْطَلِقٌ؛ زَيْدًا مُنْطَلِقًا عَلِمْتُ / زَيْدٌ مُنْطَلِقٌ عَلِمْتُ); their doer and object may be two attached pronouns of one reference (عَلِمْتُنِي قَائِمًا، عَلِمْتَكَ قَائِمًا); أَنَّ may enter upon their objects (عَلِمْتُ أَنَّ زَيْدًا قَائِمٌ)."},
  "ar": ["عَلِمْتُنِي قَائِمًا", "عَلِمْتُ أَنَّ زَيْدًا قَائِمٌ"], "notes": ["zanna-wa-akhawatuha"]},
 {"n": 52, "q": {"tr": "Ta'lîk nedir? Ne ile ta'lîk olur?", "en": "What is taʿlīq, and by what is it made?"},
  "a": {"tr": "Ta'lîk: mânen değil lafzan, vücûb üzere ameli bozmaktır. İstifham kelimesi, nefiy harfi, ibtidâ lâmı, kasem lâmı veya haberine ibtidâ lâmı giren إِنَّ-i meksûre ile olur; ef'âl-i kulûba, onların gayrı kalbî fiillere ve kendisiyle ilim talep olunan fiillere şâmildir.", "en": "Suspending the government in wording — not in meaning — of necessity. It is made by a question word, a negation particle, the lām of inception, the lām of the oath, or kasra-إِنَّ whose khabar carries the lām; it covers the verbs of the heart, other heart-verbs and the verbs by which knowledge is sought."},
  "ar": ["إِبْطَالُ الْعَمَلِ عَلَى سَبِيلِ الْوُجُوبِ لَفْظًا لَا مَعْنًى"], "notes": ["al-mutaaddi-wa-afal-al-qulub", "zanna-wa-akhawatuha"]},
 {"n": 53, "q": {"tr": "Ta'lîk ile ilgâ arasındaki fark nedir?", "en": "What is the difference between taʿlīq and ilghāʾ?"},
  "a": {"tr": "Ta'lîk lafzan ameli bozar, ilgâ hem lafzan hem mânen bozar. Ta'lîk yalnız vücûben bozar, ilgâ bazen vücûben bazen cevâzen bozar. Ta'lîk umûmîdir (ef'âl-i kulûbda ve gayrısında bulunur), ilgâ husûsîdir (yalnız ef'âl-i kulûbda).", "en": "Taʿlīq cancels government in wording, ilghāʾ in wording and in meaning. Taʿlīq cancels of necessity only; ilghāʾ sometimes of necessity, sometimes optionally. Taʿlīq is general (in the heart-verbs and others), ilghāʾ is particular (in the heart-verbs only)."},
  "ar": ["التَّعْلِيقُ", "الْإِلْغَاءُ"], "notes": ["zanna-wa-akhawatuha"]},
 {"n": 54, "q": {"tr": "Merfû cihetinden fiil kaç kısımdır?", "en": "With respect to its marfūʿ, how many kinds of verb are there?"},
  "a": {"tr": "İki: tâm ve nâkıs. Fiil aldığı merfû ile kelâm cihetinden tamam olup mansub bir habere muhtaç olmazsa tâm fiildir; merfûuna fâil, mansûbuna mef'ûl denir. Aldığı merfû ile tamam olmayıp nasb olunmuş bir ma'mûle muhtaç olursa nâkıs fiildir; merfûuna ismi, mansûbuna haberi denir.", "en": "Two: complete and deficient. A verb complete as speech with its marfūʿ, needing no manṣūb khabar, is a complete verb; its marfūʿ is its doer, its manṣūb its object. One not complete with its marfūʿ, needing a manṣūb, is deficient; its marfūʿ is its ism, its manṣūb its khabar."},
  "ar": ["الْفِعْلُ التَّامُّ", "الْفِعْلُ النَّاقِصُ"], "notes": ["al-fil-al-tamm-wal-naqis", "kana-wa-akhawatuha"]},
 {"n": 55, "q": {"tr": "Nâkıs fiil kaç kısımdır?", "en": "How many kinds of deficient verb are there?"},
  "a": {"tr": "İki. Birincisi mukârebe mânâsına delâlet etmeyendir: كَانَ، صَارَ، آلَ، رَجَعَ، حَالَ، اسْتَحَالَ، تَحَوَّلَ، ارْتَدَّ، جَاءَ، قَعَدَ، أَصْبَحَ، أَمْسَى، أَضْحَى، ظَلَّ، بَاتَ، آضَ، عَادَ، غَدَا، رَاحَ، مَا زَالَ، مَا فَتِئَ، مَا بَرِحَ، مَا وَنَى، مَا رَامَ، مَا دَامَ، لَيْسَ. İkincisi yakınlık mânâsına delâlet edendir: عَسَى، كَادَ، كَرَبَ، هَلْهَلَ، طَفِقَ، أَخَذَ، أَنْشَأَ، أَقْبَلَ، هَبَّ، جَعَلَ، عَلِقَ، أَوْشَكَ.", "en": "Two. The first does not carry the sense of nearness: كَانَ، صَارَ، آلَ، رَجَعَ، حَالَ، اسْتَحَالَ، تَحَوَّلَ، ارْتَدَّ، جَاءَ، قَعَدَ، أَصْبَحَ، أَمْسَى، أَضْحَى، ظَلَّ، بَاتَ، آضَ، عَادَ، غَدَا، رَاحَ، مَا زَالَ، مَا فَتِئَ، مَا بَرِحَ، مَا وَنَى، مَا رَامَ، مَا دَامَ، لَيْسَ. The second carries nearness: عَسَى، كَادَ، كَرَبَ، هَلْهَلَ، طَفِقَ، أَخَذَ، أَنْشَأَ، أَقْبَلَ، هَبَّ، جَعَلَ، عَلِقَ، أَوْشَكَ."},
  "ar": ["مَا لَا يَدُلُّ عَلَى مَعْنَى الْمُقَارَبَةِ", "مَا يَدُلُّ عَلَى مَعْنَى الْقُرْبِ"], "notes": ["al-fil-al-tamm-wal-naqis", "afal-al-muqaraba"]},
 {"n": 56, "q": {"tr": "Nâkıs fiillerin haberlerini kendileri üzerine takdim etmek câiz midir?", "en": "May the khabar of a deficient verb be put before it?"},
  "a": {"tr": "Câizdir. Ancak başında مَا lafzı olanlarda câiz değildir; مَا yerine إِنْ-i nâfiye getirilse yine câiz değildir; لَمْ veya لَنْ ile değiştirilirse câiz olur.", "en": "Yes. But not for those that open with مَا; nor if the negating إِنْ stands in its place; with لَمْ or لَنْ it becomes allowed."},
  "ar": ["مَا زَالَ"], "notes": ["al-fil-al-tamm-wal-naqis", "al-afal-al-naqisa-fil-kafiya"]},
 {"n": 57, "q": {"tr": "İsm-i fâil ve ism-i mef'ûlün munfasıl fâil ve mef'ûl bihde amel etmesinin şartı nedir?", "en": "On what condition do the ism fāʿil and the ism mafʿūl govern a separate doer and object?"},
  "a": {"tr": "Lâm-ı ta'rifli iken musaggar ve mevsûf olmayacak (ضُوَيْرِب، مُضَيْرِيب olmaz); amel ettikten sonra vasıflanırsa geçmiş amele zarar vermez (جَاءَنِي رَجُلٌ ضَارِبٌ غُلَامُهُ شَدِيدٌ). Lâm-ı ta'rifsiz iken mübtedâya, mevsûfa, zi'l-hâle, istifhâma veya nefye itimad etmesi şarttır (زَيْدٌ ضَارِبٌ غُلَامُهُ عَمْرًا؛ جَاءَنِي زَيْدٌ رَاكِبًا غُلَامُهُ؛ أَقَائِمٌ الزَّيْدَانِ؛ مَا قَائِمٌ الزَّيْدَانِ); mef'ûl bihi nasb etmesinde hâl ve istikbal mânâsı da şarttır. Mübalağa vezinleri فَعَّال، فَعُول، مِفْعَال da aynı hükümdedir, fakat onlarda hâl ve istikbal şart değildir.", "en": "With the article: not diminutive, not described (no ضُوَيْرِب، مُضَيْرِيب); a description after the governing does not harm it (جَاءَنِي رَجُلٌ ضَارِبٌ غُلَامُهُ شَدِيدٌ). Without the article: it must lean on a mubtadaʾ, a described noun, a ḥāl-owner, a question or a negation (زَيْدٌ ضَارِبٌ غُلَامُهُ عَمْرًا؛ جَاءَنِي زَيْدٌ رَاكِبًا غُلَامُهُ؛ أَقَائِمٌ الزَّيْدَانِ؛ مَا قَائِمٌ الزَّيْدَانِ); to put an object in naṣb it must also mean the present or future. The intensive forms فَعَّال، فَعُول، مِفْعَال follow the same rule, without the present-or-future condition."},
  "ar": ["أَقَائِمٌ الزَّيْدَانِ", "مَا قَائِمٌ الزَّيْدَانِ"], "notes": ["shurut-amal-ism-al-fail", "ism-fail", "ism-maful"]},
 {"n": 58, "q": {"tr": "Sıfat-ı müşebbehe nasıl amel eder?", "en": "How does the ṣifa mushabbaha govern?"},
  "a": {"tr": "Hâl ve istikbal mânâsı dışında ism-i fâil ve ism-i mef'ûlde aranan şartlarla, lâzım fiilinin ameli gibi amel eder; amelinde hâl ve istikbal şart değildir (زَيْدٌ حَسَنٌ وَجْهُهُ).", "en": "Under the conditions of the ism fāʿil and ism mafʿūl, except that of present-or-future, and like its own intransitive verb (زَيْدٌ حَسَنٌ وَجْهُهُ)."},
  "ar": ["زَيْدٌ حَسَنٌ وَجْهُهُ"], "notes": ["shurut-amal-ism-al-fail", "sifa-mushabbaha"]},
 {"n": 59, "q": {"tr": "İsm-i tafdîlin amel etme şartları nelerdir?", "en": "What are the conditions for the ism tafḍīl to govern?"},
  "a": {"tr": "Beştir: lafzan bir şeye sıfat olacak (o şey mâ cerâ aleyhtir); mâ cerâ aleyhin müteallakı için mânen sıfat olacak; müteallak, mâ cerâ aleyhe taalluk itibariyle mufaddal olacak; müteallak, gayra taalluk itibariyle mufaddalun aleyh olacak; kelâm menfî olacak — nefiy ile üçüncü ve dördüncü maddedeki hüküm tersine döner. مَا رَأَيْتُ رَجُلًا أَحْسَنَ فِي عَيْنِهِ الْكُحْلُ مِنْهُ فِي عَيْنِ زَيْدٍ: أَحْسَنَ, حَسُنَ fiili gibi amel edip الْكُحْلُ'ü fâil alarak ref' etmiştir (kühl meselesi).", "en": "Five: it describes a thing in wording (that thing is what it «runs on»); it describes in meaning something attached to that thing; the attached thing is the surpasser with respect to its own owner; and the surpassed with respect to another; and the speech is negated — the negation reverses the third and fourth. مَا رَأَيْتُ رَجُلًا أَحْسَنَ فِي عَيْنِهِ الْكُحْلُ مِنْهُ فِي عَيْنِ زَيْدٍ: أَحْسَنَ governs like حَسُنَ and raises الْكُحْلُ as its doer (the «kohl» case)."},
  "ar": ["مَا رَأَيْتُ رَجُلًا أَحْسَنَ فِي عَيْنِهِ الْكُحْلُ مِنْهُ فِي عَيْنِ زَيْدٍ"], "notes": ["amal-ism-al-tafdil-wal-masdar", "ism-tafdil"]},
 {"n": 60, "q": {"tr": "Masdarın amel etme şartları nelerdir?", "en": "What are the conditions for the maṣdar to govern?"},
  "a": {"tr": "Fâil ve mef'ûl bihde amel etmesinin şartı beştir: musaggar olmayacak; mevsûf olmayacak; hâle yakın olmayacak; lâm-ı ta'rif ile ma'rife olmayacak; fiilli veya fiilsiz aded, nev' veya te'kid (mef'ûl-i mutlak) olmayacak.", "en": "Five: it is not diminutive, not described, not near to the present, not made definite by the article, and not a maṣdar of number, kind or emphasis (a mafʿūl muṭlaq), with or without its verb."},
  "ar": ["أَعْجَبَنِي ضَرْبُ زَيْدٍ"], "notes": ["amal-ism-al-tafdil-wal-masdar", "imal-al-masdar"]},
 {"n": 61, "q": {"tr": "İsm-i muzâf ne amel eder? İzâfetin şartı nedir?", "en": "What government does the annexed noun exercise, and what is the condition of annexation?"},
  "a": {"tr": "Cer amel eder. İzâfetin şartı üçtür: izâfet için muzâfın tenvinden ve tenvinin nâibinden soyulması; muzâfın umûmîlik ve husûsîlikte muzâfun ileyhe müsâvî olmaması; muzâfın mutlak olarak muzâfun ileyhten daha hususî olmaması.", "en": "It governs in jarr. Three conditions: the annexed is stripped, for the annexation, of its tanwīn and of what stands for it; it is not equal to the annexed-to in generality; and it is not, absolutely, more particular than the annexed-to."},
  "ar": ["الِاسْمُ الْمُضَافُ"], "notes": ["al-mudaf-wa-nawa-al-idafa"]},
 {"n": 62, "q": {"tr": "İzâfet kaç kısımdır? İzâfet-i mâneviyye nedir, şartı nedir, kaç mânâya gelir, ne ifade eder?", "en": "How many kinds of annexation? What is annexation of meaning, its condition, its senses, and what it brings?"},
  "a": {"tr": "İki: mâneviyye ve lafziyye. Mâneviyye: muzâfın, ma'mûlüne muzâf olan sıfat olmamasıdır. Şartı: muzâfın ma'rifelikten soyulmuş olması; soyulmazsa izâfet fayda vermez, hâsılı tahsil lâzım gelir. Üç mânâya gelir: muzâfun ileyh muzâfın cinsi ise مِنْ mânâsına (خَاتَمُ فِضَّةٍ), zarfı ise فِي mânâsına (ضَرْبُ الْيَوْمِ), ikisi de değilse لَام mânâsına (غُلَامُ زَيْدٍ). Muzâfun ileyh ma'rife olup muzâf غَيْر، شِبْه، مِثْل'in gayrı ise ta'rif (غُلَامُ زَيْدٍ), nekre ise tahsis (غُلَامُ رَجُلٍ) ifade eder.", "en": "Two: of meaning and of wording. Of meaning: the annexed is not an adjective annexed to its own governed word. Its condition: the annexed is stripped of definiteness; else the annexation gains nothing, acquiring what is already had. Three senses: مِنْ when the annexed-to is the annexed's kind (خَاتَمُ فِضَّةٍ), فِي when its container (ضَرْبُ الْيَوْمِ), لَام otherwise (غُلَامُ زَيْدٍ). With a definite annexed-to it brings definiteness unless the annexed is غَيْر، شِبْه، مِثْل (غُلَامُ زَيْدٍ); with an indefinite one, particularisation (غُلَامُ رَجُلٍ)."},
  "ar": ["أَنْ يَكُونَ الْمُضَافُ غَيْرَ صِفَةٍ مُضَافَةٍ إِلَى مَعْمُولِهَا", "خَاتَمُ فِضَّةٍ", "غُلَامُ زَيْدٍ"], "notes": ["al-mudaf-wa-nawa-al-idafa", "idafa-definiteness"]},
 {"n": 63, "q": {"tr": "İzâfet-i lafziyyenin tarifi nedir? Ne ifade eder? مَرَرْتُ بِرَجُلٍ حَسَنِ الْوَجْهِ ve مَرَرْتُ بِزَيْدٍ حَسَنِ الْوَجْهِ câiz midir?", "en": "How is annexation of wording defined, what does it bring, and are مَرَرْتُ بِرَجُلٍ حَسَنِ الْوَجْهِ and مَرَرْتُ بِزَيْدٍ حَسَنِ الْوَجْهِ allowed?"},
  "a": {"tr": "Lafziyye: muzâfın, ma'mûlüne muzâf olan sarfî sıfat olmasıdır (ضَارِبُ زَيْدٍ، زَيْدٌ حَسَنُ الْوَجْهِ، مَعْمُورُ الدَّارِ، الضَّارِبَا زَيْدٍ). Lafızda yalnız hafiflik ifade eder; ta'rif ve tahsis ifade etmez. Bu sebeple مَرَرْتُ بِرَجُلٍ حَسَنِ الْوَجْهِ câizdir (حَسَنُ الْوَجْهِ ma'rifelik ifade etmediğinden nekre رَجُلٍ'e sıfat olur); مَرَرْتُ بِزَيْدٍ حَسَنِ الْوَجْهِ câiz değildir (ma'rife زَيْد'e sıfat olamaz).", "en": "The annexed is a derived adjective annexed to its own governed word (ضَارِبُ زَيْدٍ، زَيْدٌ حَسَنُ الْوَجْهِ، مَعْمُورُ الدَّارِ، الضَّارِبَا زَيْدٍ). It brings only lightness of wording — neither definiteness nor particularisation. Hence مَرَرْتُ بِرَجُلٍ حَسَنِ الْوَجْهِ is allowed (حَسَنُ الْوَجْهِ, not definite, describes the indefinite رَجُلٍ); مَرَرْتُ بِزَيْدٍ حَسَنِ الْوَجْهِ is not (it cannot describe the definite زَيْد)."},
  "ar": ["أَنْ يَكُونَ الْمُضَافُ صِفَةً مُضَافَةً إِلَى مَعْمُولِهَا", "مَرَرْتُ بِرَجُلٍ حَسَنِ الْوَجْهِ"], "notes": ["idafa-lafziyya", "al-mudaf-wa-nawa-al-idafa"]},
 {"n": 64, "q": {"tr": "الضَّارِبَا زَيْدٍ، الضَّارِبُو زَيْدٍ، الضَّارِبُ زَيْدٍ ve الضَّارِبُ الرَّجُلِ misallerinden hangileri câizdir? Niçin?", "en": "Which of الضَّارِبَا زَيْدٍ، الضَّارِبُو زَيْدٍ، الضَّارِبُ زَيْدٍ and الضَّارِبُ الرَّجُلِ are allowed, and why?"},
  "a": {"tr": "الضَّارِبَا زَيْدٍ ve الضَّارِبُو زَيْدٍ câizdir: izâfetle tesniye ve cem' nûnları düşüp hafiflik hâsıl olur. الضَّارِبُ زَيْدٍ câiz değildir: tenvin lâm sebebiyle zaten düşmüş, izâfetle hafiflik hâsıl olmamıştır. الضَّارِبُ الرَّجُلِ, muzâfı sarfî sıfat ve muzâfun ileyhi lâm ile ma'rife cins ismi olmakta حَسَنُ الْوَجْهِ ile ortak olduğundan ona hamlen câizdir; الضَّارِبُكَ de sıfatın zamire muzâf olmasında ضَارِبُكَ ile ortak olduğundan ona hamlen câizdir.", "en": "الضَّارِبَا زَيْدٍ and الضَّارِبُو زَيْدٍ: annexation drops the nūn of dual and plural, so the word lightens. الضَّارِبُ زَيْدٍ is not allowed: the tanwīn already went with the article, so annexation lightens nothing. الضَّارِبُ الرَّجُلِ is allowed by analogy with حَسَنُ الْوَجْهِ — a derived adjective annexed to a generic noun with the article; الضَّارِبُكَ by analogy with ضَارِبُكَ — an adjective annexed to a pronoun."},
  "ar": ["الضَّارِبَا زَيْدٍ", "الضَّارِبُ الرَّجُلِ"], "notes": ["idafa-lafziyya"]},
 {"n": 65, "q": {"tr": "İsm-i mübhem-i tâm nasıl amel eder? Ne ile tamamlanır?", "en": "How does the complete vague noun govern, and by what is it completed?"},
  "a": {"tr": "Nekre bir ismi temyiz alıp nasb eder. Tamam olması, yani izâfetin imkânsız olduğu bir hâl üzere bulunması beş şeyden biriyle olur: bizâtihi (mübhem zamirde: رُبَّهُ رَجُلًا، يَا لَهُ رَجُلًا، نِعْمَ رَجُلًا; ism-i işârette: مَاذَا أَرَادَ اللهُ بِهَذَا مَثَلًا); lafzan veya takdiren tenvinle (رِطْلٌ زَيْتًا؛ مَثَاقِيلُ ذَهَبًا، أَحَدَ عَشَرَ رَجُلًا); tesniye nûnu ile (مَنَوَانِ سَمْنًا); şibh-i cem' nûnu ile (عِشْرُونَ دِرْهَمًا: عِشْرُونَ'den تِسْعُونَ'e); izâfetle (مِلْؤُهُ عَسَلًا).", "en": "It takes an indefinite noun as its tamyīz and puts it in naṣb. Its completeness — a state in which annexation is impossible — comes by one of five: in itself (the vague pronoun: رُبَّهُ رَجُلًا، يَا لَهُ رَجُلًا، نِعْمَ رَجُلًا; the demonstrative: مَاذَا أَرَادَ اللهُ بِهَذَا مَثَلًا); by a tanwīn stated or implied (رِطْلٌ زَيْتًا؛ مَثَاقِيلُ ذَهَبًا، أَحَدَ عَشَرَ رَجُلًا); by the dual's nūn (مَنَوَانِ سَمْنًا); by the plural-like nūn (عِشْرُونَ دِرْهَمًا, from twenty to ninety); by annexation (مِلْؤُهُ عَسَلًا)."},
  "ar": ["عِشْرُونَ دِرْهَمًا", "رِطْلٌ زَيْتًا", "مَنَوَانِ سَمْنًا"], "notes": ["al-ism-al-mubham-al-tamm", "tamyiz"]},
 {"n": 66, "q": {"tr": "Esmâ-i adedin mümeyyizlerinin durumu nedir?", "en": "What is the standing of the number nouns' specifiers?"},
  "a": {"tr": "Üçten ona kadar olan adedlerin mümeyyizi mecrûr ve cem'dir (ثَلَاثَةُ رِجَالٍ). Üç yüzden dokuz yüze kadar olanların mümeyyizi müfred ve mecrûrdur (ثَلَاثُمِائَةِ رَجُلٍ). On birden doksan dokuza kadar olanların mümeyyizi dâima müfred ve mansubdur (أَحَدَ عَشَرَ رَجُلًا). مِائَة ve أَلْف'in, tesniyelerinin ve أَلْف'in cem'inin mümeyyizi müfred ve mecrûrdur (مِائَةُ رَجُلٍ وَأَلْفُ دِرْهَمٍ).", "en": "From three to ten the specifier is plural and majrūr (ثَلَاثَةُ رِجَالٍ). From three hundred to nine hundred, singular and majrūr (ثَلَاثُمِائَةِ رَجُلٍ). From eleven to ninety-nine, always singular and manṣūb (أَحَدَ عَشَرَ رَجُلًا). For مِائَة and أَلْف, their duals and the plural of أَلْف, singular and majrūr (مِائَةُ رَجُلٍ وَأَلْفُ دِرْهَمٍ)."},
  "ar": ["ثَلَاثَةُ رِجَالٍ", "أَحَدَ عَشَرَ رَجُلًا", "مِائَةُ رَجُلٍ"], "notes": ["al-ism-al-mubham-al-tamm", "asma-al-adad-fil-kafiya"]},
 {"n": 67, "q": {"tr": "Mânâ-yı fiil nedir? Mânâ-yı fiiller nelerdir?", "en": "What is «the sense of the verb», and which words carry it?"},
  "a": {"tr": "Kendisinden fiil mânâsı anlaşılan her lafızdır: esmâ-i ef'âl, zarf-ı müstakar, ism-i mensûb, ism-i müsteâr, kendisinden sıfat mânâsı anlaşılan her isim, ism-i işâret, لَيْتَ، لَعَلَّ, nidâ, teşbih, tenbih ve nefiy harfleri ve benzerleri. Bunlar fiilin ma'mûllerinden fâil ve mef'ûl bihin gayrısında (hâl, zarf) amel ederler. Esmâ-i ef'âl, adlandırıldığı şeyin amelini yapar; ma'mûlü kendi üzerine takaddüm etmez; emir mânâsına (هَا زَيْدًا = خُذْهُ، تَرَاكِ زَيْدًا = اتْرُكْهُ) veya mâzî mânâsına (هَيْهَاتَ الْأَمْرُ = بَعُدَ، شَتَّانَ زَيْدٌ وَعَمْرٌو = افْتَرَقَا، سَرْعَانَ زَيْدٌ = قَرُبَ) olur.", "en": "Any word from which a verb's meaning is understood: the noun-verbs, the settled ẓarf, the nisba noun, the borrowed noun, any noun understood as a quality, the demonstrative, لَيْتَ، لَعَلَّ, the particles of calling, likening, alerting and negation, and the like. These govern the verb's dependents other than the doer and the object — the ḥāl and the ẓarf. A noun-verb does the work of the verb it names; its governed word never precedes it; it means a command (هَا زَيْدًا = خُذْهُ، تَرَاكِ زَيْدًا = اتْرُكْهُ) or a past (هَيْهَاتَ الْأَمْرُ = بَعُدَ، شَتَّانَ زَيْدٌ وَعَمْرٌو = افْتَرَقَا، سَرْعَانَ زَيْدٌ = قَرُبَ)."},
  "ar": ["كُلُّ لَفْظٍ يُفْهَمُ مِنْهُ مَعْنَى فِعْلٍ", "هَيْهَاتَ الْأَمْرُ", "شَتَّانَ زَيْدٌ وَعَمْرٌو"], "notes": ["mana-al-fil-wa-asma-al-afal", "ism-fil"]},
 {"n": 68, "q": {"tr": "Zarf-ı müstakarrın fâil ve mef'ûl bihde amel etmesinin şartı nedir?", "en": "On what condition does the settled ẓarf govern a doer and an object?"},
  "a": {"tr": "İsm-i fâil ve ism-i mef'ûldeki itimad şartıyla veya mevsûle itimad şartıyla amel eder (زَيْدٌ فِي الدَّارِ أَبُوهُ؛ جَاءَنِي الَّذِي فِي الدَّارِ أَبُوهُ). Zâhirî fâil ve mef'ûl bihin gayrısında (hâl ve zarf) şartsız amel eder.", "en": "On the leaning-condition of the ism fāʿil and ism mafʿūl, or leaning on a relative (زَيْدٌ فِي الدَّارِ أَبُوهُ؛ جَاءَنِي الَّذِي فِي الدَّارِ أَبُوهُ). Outside an overt doer and object — the ḥāl and the ẓarf — it governs without condition."},
  "ar": ["زَيْدٌ فِي الدَّارِ أَبُوهُ"], "notes": ["mana-al-fil-wa-asma-al-afal", "zarf-mustaqarr-wa-laghw"]},
 {"n": 69, "q": {"tr": "İsm-i mensûb ne amel eder?", "en": "What does the nisba noun govern?"},
  "a": {"tr": "İsm-i mef'ûl gibi, ism-i mef'ûldeki şartlarla amel eder (مَرَرْتُ بِرَجُلٍ هَاشِمِيٍّ أَخُوهُ).", "en": "Like the ism mafʿūl and on its conditions (مَرَرْتُ بِرَجُلٍ هَاشِمِيٍّ أَخُوهُ)."},
  "ar": ["مَرَرْتُ بِرَجُلٍ هَاشِمِيٍّ أَخُوهُ"], "notes": ["mana-al-fil-wa-asma-al-afal", "ism-mansub"]},
 {"n": 70, "q": {"tr": "İsm-i müsteâr ne amel eder?", "en": "What does the borrowed noun govern?"},
  "a": {"tr": "İsm-i mef'ûl gibi amel eder: مَرَرْتُ بِرَجُلٍ أَسَدٍ غُلَامُهُ misalinde مُجْتَرِئ (cesur) mânâsında olan أَسَد lafzı gibi.", "en": "Like the ism mafʿūl: as أَسَد meaning «bold» in مَرَرْتُ بِرَجُلٍ أَسَدٍ غُلَامُهُ."},
  "ar": ["مَرَرْتُ بِرَجُلٍ أَسَدٍ غُلَامُهُ"], "notes": ["mana-al-fil-wa-asma-al-afal"]},
 {"n": 71, "q": {"tr": "Âmil-i mânevî nedir? Kaç kısımdır?", "en": "What is the governor of meaning, and how many kinds has it?"},
  "a": {"tr": "Kendisinde lisan için hazz olmayıp kalp ile bilinen bir mânâdır. İki kısımdır: mübtedâ ve haberi ref' eder — bu, isnad için lafzî âmillerden soyulmaktır (زَيْدٌ قَائِمٌ); fiil-i muzâriyi ref' eder — bu, bizâtihi isim mevkiinde bulunmaktır.", "en": "A meaning in which the tongue has no share, known by the heart. Two kinds: what raises the mubtadaʾ and the khabar — their being stripped of wording governors for the predication (زَيْدٌ قَائِمٌ); and what raises the muḍāriʿ — its standing in itself where a noun stands."},
  "ar": ["مَا لَا يَكُونُ لِلِّسَانِ فِيهِ حَظٌّ وَإِنَّمَا هُوَ مَعْنًى يُعْرَفُ بِالْقَلْبِ"], "notes": ["al-amil-al-manawi", "mudari-marfu"]},
]
